 "content": "def transform(grid):
    """Recolor each color-1 component to the color of an identical-shape key."""
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            minr = min(y for y, x in cells)
            minc = min(x for y, x in cells)
            shape = frozenset((y - minr, x - minc) for y, x in cells)
            components.append((color, cells, shape))

    keys = {}
    for color, cells, shape in components:
        if color != 1:
            keys[shape] = color
    out = [row[:] for row in grid]
    for color, cells, shape in components:
        if color == 1 and shape in keys:
            for r, c in cells:
                out[r][c] = keys[shape]
    return out
